 for(const v of this.particles){v.x+=v.vx*dt;v.y+=v.vy*dt;v.life-=dt}this.particles=this.particles.filter(v=>v.life>0);for(const e of this.effects)e.life-=dt;this.effects=this.effects.filter(e=>e.life>0);
 if(this.mode!=='play')return;
