 if(this.mode==='play'&&this.pickup&&Math.hypot(p.x-this.pickup.x,p.y-this.pickup.y)<38){if(this.pickup.type==='heart'){if(p.hp<p.maxHp){p.hp=Math.min(p.maxHp,p.hp+1);this.pickup=null;this.emit('heal')}}else{this.floor++;p.hp=Math.min(p.maxHp,p.hp+2);this.generate();this.emit('toast',{text:'进入下一章，恢复 2 点生命。'});return}}
 if(r.clear&&this.mode==='play'){const d=this.doors();if(p.x<58&&Math.abs(p.y-300)<48&&d.left){this.enter(this.roomId-1,'left');return}if(p.x>902&&Math.abs(p.y-300)<48&&d.right){this.enter(this.roomId+1,'right');return}if(p.y<58&&Math.abs(p.x-480)<48&&d.top){this.enter(this.roomId-(this.gridSize||3),'top');return}if(p.y>542&&Math.abs(p.x-480)<48&&d.bottom){this.enter(this.roomId+(this.gridSize||3),'bottom');return}}
